-- 0001: sync-ready server columns (Phase 11 part 1).
-- Generated by drizzle-kit, then hand-completed (never applied before):
--  * CREATE SEQUENCE sync_seq comes FIRST: the new server_seq column
--    defaults reference it (drizzle-kit does not emit CREATE SEQUENCE).
--  * categories.slug is added NULLABLE, backfilled from the stable
--    kind+name -> slug map (identical to packages/local/src/seed.ts), de-
--    duplicated against pre-sync user rows, then SET NOT NULL + UNIQUE.
--    A plain ADD COLUMN ... NOT NULL would fail on tables that already
--    have rows.
--  * stamp_server_seq() + one BEFORE INSERT OR UPDATE trigger per synced
--    table: assigns nextval('sync_seq') ONLY when server_seq IS NULL and
--    leaves explicit values untouched, so replayed pushes (upserts that
--    carry the original server_seq) keep a stable pull cursor, and plain
--    UPDATEs never move a row's cursor. In practice the column DEFAULT
--    already fills fresh inserts, so the trigger is a safety net.
-- Must stay in sync with apps/api/src/db/schema.ts (+seed.ts slugs) and
-- docs/BACKGROUND_SCHEMA.md.
CREATE SEQUENCE "sync_seq";--> statement-breakpoint
CREATE TABLE "devices" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"token_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_seen_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	CONSTRAINT "devices_token_hash_unique" UNIQUE("token_hash")
);
--> statement-breakpoint
ALTER TABLE "accounts" ADD COLUMN "deleted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "accounts" ADD COLUMN "server_seq" bigint DEFAULT nextval('sync_seq') NOT NULL;--> statement-breakpoint
ALTER TABLE "categories" ADD COLUMN "slug" text;--> statement-breakpoint
UPDATE "categories" SET "slug" = CASE
	WHEN "kind" = 'expense' AND "name" = 'Belanja' THEN 'expense-shopping'
	WHEN "kind" = 'expense' AND "name" = 'Makanan & Minuman' THEN 'expense-food-drink'
	WHEN "kind" = 'expense' AND "name" = 'Tagihan & Utilitas' THEN 'expense-bills-utilities'
	WHEN "kind" = 'expense' AND "name" = 'Transportasi' THEN 'expense-transport'
	WHEN "kind" = 'expense' AND "name" = 'Kesehatan' THEN 'expense-health'
	WHEN "kind" = 'expense' AND "name" = 'Hiburan' THEN 'expense-entertainment'
	WHEN "kind" = 'expense' AND "name" = 'Pendidikan' THEN 'expense-education'
	WHEN "kind" = 'expense' AND "name" = 'Lainnya' THEN 'expense-other'
	WHEN "kind" = 'income' AND "name" = 'Gaji' THEN 'income-salary'
	WHEN "kind" = 'income' AND "name" = 'Bonus' THEN 'income-bonus'
	WHEN "kind" = 'income' AND "name" = 'Proyek' THEN 'income-project'
	WHEN "kind" = 'income' AND "name" = 'Hadiah' THEN 'income-gift'
	WHEN "kind" = 'income' AND "name" = 'Lainnya' THEN 'income-other'
	ELSE 'custom-' || "id"::text
END WHERE "slug" IS NULL;--> statement-breakpoint
WITH "ranked" AS (
	SELECT "id", "slug", row_number() OVER (PARTITION BY "slug" ORDER BY "id") AS "rn" FROM "categories"
) UPDATE "categories" AS "c" SET "slug" = "ranked"."slug" || '-' || substring("ranked"."id"::text, 1, 8) FROM "ranked" WHERE "c"."id" = "ranked"."id" AND "ranked"."rn" > 1;--> statement-breakpoint
ALTER TABLE "categories" ALTER COLUMN "slug" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "transaction_items" ADD COLUMN "deleted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transaction_items" ADD COLUMN "server_seq" bigint DEFAULT nextval('sync_seq') NOT NULL;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "deleted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transactions" ADD COLUMN "server_seq" bigint DEFAULT nextval('sync_seq') NOT NULL;--> statement-breakpoint
ALTER TABLE "transfers" ADD COLUMN "deleted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "transfers" ADD COLUMN "server_seq" bigint DEFAULT nextval('sync_seq') NOT NULL;--> statement-breakpoint
CREATE INDEX "accounts_server_seq_idx" ON "accounts" USING btree ("server_seq");--> statement-breakpoint
CREATE INDEX "tx_item_server_seq_idx" ON "transaction_items" USING btree ("server_seq");--> statement-breakpoint
CREATE INDEX "tx_server_seq_idx" ON "transactions" USING btree ("server_seq");--> statement-breakpoint
CREATE INDEX "transfers_server_seq_idx" ON "transfers" USING btree ("server_seq");--> statement-breakpoint
ALTER TABLE "categories" ADD CONSTRAINT "categories_slug_unique" UNIQUE("slug");--> statement-breakpoint
CREATE OR REPLACE FUNCTION "stamp_server_seq"() RETURNS trigger AS $$
BEGIN
	IF NEW."server_seq" IS NULL THEN
		NEW."server_seq" := nextval('sync_seq');
	END IF;
	RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER "accounts_stamp_server_seq" BEFORE INSERT OR UPDATE ON "accounts" FOR EACH ROW EXECUTE FUNCTION "stamp_server_seq"();--> statement-breakpoint
CREATE TRIGGER "transactions_stamp_server_seq" BEFORE INSERT OR UPDATE ON "transactions" FOR EACH ROW EXECUTE FUNCTION "stamp_server_seq"();--> statement-breakpoint
CREATE TRIGGER "transaction_items_stamp_server_seq" BEFORE INSERT OR UPDATE ON "transaction_items" FOR EACH ROW EXECUTE FUNCTION "stamp_server_seq"();--> statement-breakpoint
CREATE TRIGGER "transfers_stamp_server_seq" BEFORE INSERT OR UPDATE ON "transfers" FOR EACH ROW EXECUTE FUNCTION "stamp_server_seq"();
